(function(){
  if (window.__coulInstalled__) return;
  window.__coulInstalled__ = true;
  var canvas = document.getElementById('coulCanvas');
  var ctx = canvas.getContext('2d');
  var q1Slider = document.getElementById('q1Slider');
  var q1Val = document.getElementById('q1Val');
  var q2Slider = document.getElementById('q2Slider');
  var q2Val = document.getElementById('q2Val');
  var rSlider = document.getElementById('rSlider');
  var rVal = document.getElementById('rVal');
  var out = document.getElementById('coulOut');
  var playBtn = document.getElementById('playBtn');
  var K = 9e9;
  var running = false, phase = 0;
  window.simState = { q1: 3, q2: -2, r: 4, F: 0, attract: true, running: false, phase: 0 };
  function compute(){
    var q1 = parseFloat(q1Slider.value), q2 = parseFloat(q2Slider.value), r = parseFloat(rSlider.value);
    var F = K * Math.abs(q1 * q2) * 1e-12 / Math.pow(r / 100, 2);
    var attract = (q1 * q2) < 0;
    window.simState.q1 = q1; window.simState.q2 = q2; window.simState.r = r;
    window.simState.F = F; window.simState.attract = attract;
    return { q1: q1, q2: q2, r: r, F: F, attract: attract };
  }
  function drawCharge(x, y, q, color){
    var rad = 16 + Math.min(Math.abs(q) * 3, 14);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(x, y, rad, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#0f172a'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(x, y, rad, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 16px sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(q >= 0 ? '+' : '−', x, y + 1);
  }
  function arrow(x1, y1, x2, y2, color){
    var dx = x2 - x1, dy = y2 - y1;
    var len = Math.sqrt(dx * dx + dy * dy);
    if (len < 2) return;
    var ux = dx / len, uy = dy / len;
    var hlen = Math.max(10, Math.min(len - 4, 34));
    var hx = x1 + ux * hlen, hy = y1 + uy * hlen;
    ctx.strokeStyle = color; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(hx, hy); ctx.stroke();
    var ah = 8;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(hx + ux * ah, hy + uy * ah);
    ctx.lineTo(hx - uy * ah + ux * 2, hy + ux * ah + uy * 2);
    ctx.lineTo(hx + uy * ah + ux * 2, hy - ux * ah + uy * 2);
    ctx.closePath(); ctx.fill();
    return { x: hx, y: hy, ux: ux, uy: uy };
  }
  function draw(){
    var p = compute();
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    var CX = canvas.width / 2, CY = canvas.height / 2;
    var half = (p.r / 10) * (canvas.width * 0.38);
    var x1 = CX - half, x2 = CX + half;
    ctx.strokeStyle = '#e2e8f0'; ctx.lineWidth = 1;
    ctx.setLineDash([5, 5]);
    ctx.beginPath(); ctx.moveTo(x1, CY); ctx.lineTo(x2, CY); ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#64748b'; ctx.font = '12px sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    ctx.fillText('r = ' + p.r.toFixed(1) + ' cm', CX, CY + 24);
    var c1 = p.q1 >= 0 ? '#dc2626' : '#2563eb';
    var c2 = p.q2 >= 0 ? '#dc2626' : '#2563eb';
    drawCharge(x1, CY, p.q1, c1);
    drawCharge(x2, CY, p.q2, c2);
    var flen = Math.min(160, 14 + Math.log10(1 + p.F) * 26);
    var dir = p.attract ? 1 : -1;
    arrow(x1 + dir * 18, CY, x1 + dir * (18 + flen), CY, '#dc2626');
    arrow(x2 - dir * 18, CY, x2 - dir * (18 + flen), CY, '#dc2626');
    if (running) {
      phase += 0.03;
      var t = (phase % 2) / 2;
      var px, py;
      if (t < 0.5) { px = x1 + (x2 - x1) * (t * 2); py = CY; }
      else { px = x2 - (x2 - x1) * ((t - 0.5) * 2); py = CY; }
      ctx.fillStyle = '#f59e0b';
      ctx.beginPath(); ctx.arc(px, py, 5, 0, Math.PI * 2); ctx.fill();
    }
    q1Val.textContent = (p.q1 > 0 ? '+' : '') + p.q1.toFixed(1);
    q2Val.textContent = (p.q2 > 0 ? '+' : '') + p.q2.toFixed(1);
    rVal.textContent = p.r.toFixed(1);
    out.textContent = 'F = ' + (p.F >= 10000 ? p.F.toFixed(0) : p.F.toFixed(1)) + ' N | قوة ' + (p.attract ? 'تجاذب' : 'تنافر');
    window.simState.phase = phase;
  }
  playBtn.addEventListener('click', function(){
    running = !running;
    window.simState.running = running;
    playBtn.textContent = running ? 'إيقاف' : 'تشغيل الحركة';
  });
  q1Slider.addEventListener('input', function(){});
  q2Slider.addEventListener('input', function(){});
  rSlider.addEventListener('input', function(){});
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  function loop(){ draw(); requestAnimationFrame(loop); }
  loop();
})();
